// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract FirmwareRegistry {
    struct FirmwareInfo {
        string version;      // Firmware version (e.g., "0x0102" or "v1.2")
        bytes32 hash;        // SHA-256 hash of the firmware image
        string cid;          // IPFS CID of the firmware file
        bytes signature;     // Digital signature produced by the manufacturer
        uint256 timestamp;   // Publication timestamp
    }

    // Mapping from firmware version to its metadata
    mapping(string => FirmwareInfo) public firmwareByVersion;

    // Event emitted when firmware metadata is published
    event FirmwarePublished(
        string version,
        bytes32 hash,
        string cid,
        bytes signature,
        uint256 timestamp
    );

    /**
     * @notice Publish new firmware metadata to the registry.
     * @param _version The firmware version.
     * @param _hash The SHA-256 hash of the firmware image.
     * @param _cid The IPFS CID for the firmware file.
     * @param _signature The digital signature for the firmware hash.
     */
    function publishFirmware(
        string memory _version,
        bytes32 _hash,
        string memory _cid,
        bytes memory _signature
    ) public {
        FirmwareInfo memory info = FirmwareInfo({
            version: _version,
            hash: _hash,
            cid: _cid,
            signature: _signature,
            timestamp: block.timestamp
        });

        firmwareByVersion[_version] = info;
        emit FirmwarePublished(_version, _hash, _cid, _signature, block.timestamp);
    }
}

